204	/** @brief 一段文字的量：advance（排版宽）+ 首字墨迹偏移 + 墨迹宽。 */
205	typedef struct {
206	    int adv;
207	    int ink_x0;
208	    int ink_w;
209	} sb_text_metrics_t;
210	
211	/**
212	 * @brief 12 px 状态栏字体里实际用到的 13 个字形的**渲染墨迹**列（相对笔位）。
213	 *
214	 * @details `lv_font_get_glyph_dsc()` 给的 `box_w` 是字模框，不等于屏上墨迹：
215	 *          这份 2 bpp 字模把多行像素连续打包（`stride == 0`），且框的左/右
216	 *          各可能有全空列（如 `%` 框 12 列，只有第 1..10 列有墨）。设计又要求
217	 *          **按墨迹**对齐（时间 x0=2；电量只画图标、不排文字），所以按实测表算。
218	 *          数值来自 /tmp 下的字模探针（逐像素解包 `helm_ui_12` 的 2 bpp 流，
219	 *          与模拟器截图逐列核对）；字符串只可能是 `0-9 : % -`。
220	 *          ⚠ 换状态栏字体或字号后必须重测本表。
221	 */
222	typedef struct {
223	    char ch;
224	    int8_t ink0;
225	    int8_t ink1;
226	} sb_glyph_ink_t;
227	
228	static const sb_glyph_ink_t s_glyph_ink[] = {
229	    { '0', 0, 6 }, { '1', 1, 3 }, { '2', 1, 6 }, { '3', 1, 6 },
230	    { '4', 0, 7 }, { '5', 1, 6 }, { '6', 1, 6 }, { '7', 1, 6 },
231	    { '8', 1, 6 }, { '9', 1, 6 }, { ':', 1, 1 }, { '%', 1, 10 },
232	    { '-', 1, 6 },
233	};
234	
235	static bool sb_glyph_ink_of(char ch, int * ink0, int * ink1)
236	{
237	    for (size_t i = 0; i < sizeof(s_glyph_ink) / sizeof(s_glyph_ink[0]); i++) {
238	        if (s_glyph_ink[i].ch == ch) {
239	            *ink0 = s_glyph_ink[i].ink0;
240	            *ink1 = s_glyph_ink[i].ink1;
241	            return true;
242	        }
243	    }
244	    return false;
245	}
246	
247	/**
248	 * @brief 量时间/电量这类纯 ASCII 短串的 advance 与**墨迹**边界。
249	 *
250	 * @details 设计按墨迹对齐（时间墨迹 x0=2；电量只画图标），而 12 px 点阵的
251	 *          side bearing 与空列都不为 0，所以不能拿 advance 当墨迹用。
252	 *          字符串只可能是 `0-9 : % -`，按字节迭代 + 上面的实测表即可。
253	 */
254	static void sb_text_measure(const char * txt, sb_text_metrics_t * m)
255	{
256	    lv_point_t sz;
257	    int pen = 0;
258	    int minx = 0x7FFF;
259	    int maxx = -0x8000;
260	
261	    lv_text_get_size(&sz, txt, s_font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
262	    m->adv = (int)sz.x;
263	
264	    for (const char * p = txt; *p != '\0'; p++) {
265	        const uint32_t cp = (uint8_t)*p;
266	        int ink0;
267	        int ink1;
268	
269	        if (sb_glyph_ink_of((char)cp, &ink0, &ink1)) {
270	            ink0 += pen;
271	            ink1 += pen;
272	        } else {
273	            ink0 = pen;
274	            ink1 = pen + (int)lv_font_get_glyph_width(s_font, cp, 0) - 1;
275	        }
276	
277	        if (ink0 < minx) {
278	            minx = ink0;
279	        }
280	        if (ink1 > maxx) {
281	            maxx = ink1;
282	        }
283	        pen += (int)lv_font_get_glyph_width(s_font, cp, 0);
284	    }
285	
286	    if (maxx < minx) {
287	        m->ink_x0 = 0;
288	        m->ink_w = 0;
289	    } else {
290	        m->ink_x0 = minx;
291	        m->ink_w = maxx - minx + 1;
292	    }
293	}
