309	/* ── 调色板 ─────────────────────────────────────────────────────────── */
310	
311	static uint32_t sb_pal_signature(const struct helm_pal_t * pal)
312	{
313	    if (pal == NULL) {
314	        return 0;
315	    }
316	
317	    /* 只关心顶栏用到的几支：任一支变了就重上色。 */
318	    return pal->paper ^ (pal->hair << 1) ^ (pal->ink << 2) ^
319	           (pal->track << 3) ^ (pal->gps_dead << 4) ^ (pal->ban_nav << 5);
320	}
321	
322	static void sb_palette_apply(bool force)
323	{
324	    const struct helm_pal_t * pal = helm_pal_active();
325	    uint32_t sig = sb_pal_signature(pal);
326	
327	    if (!force && sig == s_pal_sig) {
328	        return;
329	    }
330	    s_pal_sig = sig;
331	
332	    lv_obj_set_style_bg_color(s_bg, helm_color(HELM_COLOR_PAPER), 0);
333	    lv_obj_set_style_bg_color(s_hair, helm_color(HELM_COLOR_HAIR), 0);
334	    lv_obj_set_style_text_color(s_time, helm_color(HELM_COLOR_INK), 0);
335	
336	    for (int k = 0; k < SB_SLOT_N; k++) {
337	        s_slot[k].tone_last = SB_TONE_NONE;
338	        s_slot[k].dot_last = 0;
339	    }
340	    s_batt_tone_last = SB_TONE_NONE;
341	    s_rec_last = 0;
342	}
