344	/* ── 图标/圆点 ───────────────────────────────────────────────────────── */
345	
346	static void sb_slot_place(int k)
347	{
348	    sb_slot_t * s = &s_slot[k];
349	    int x0 = s_ink_x[k];
350	
351	    if (x0 < 0) {
352	        return;
353	    }
354	
355	    if (k == SB_BAT) {
356	        /* 自绘电池：体从 x0 起，右极贴在体右侧；墨迹总宽 22。 */
357	        if (s_batt_body != NULL) {
358	            lv_obj_set_pos(s_batt_body, x0, SB_BATT_BODY_Y);
359	        }
360	        if (s_batt_nub != NULL) {
361	            lv_obj_set_pos(s_batt_nub, x0 + SB_BATT_BODY_W,
362	                           SB_BATT_BODY_Y + (SB_BATT_BODY_H - SB_BATT_NUB_H) / 2);
363	        }
364	        return;
365	    }
366	
367	    if (s->ico == NULL) {
368	        return;
369	    }
370	
371	    lv_obj_set_pos(s->ico, x0 + s->cx_off - SB_ICON_PX / 2,
372	                   SB_ICON_CY - SB_ICON_PX / 2);
373	    if (s->dot != NULL) {
374	        lv_obj_set_pos(s->dot, x0 + s->dot_dx, SB_DOT_Y);
375	    }
376	}
