378	/**
379	 * @brief 上一次色 + 显隐（幂等）。
380	 *
381	 * @param tone    本拍语义色；SB_TONE_HIDE 表示数据层就不显示。
382	 * @param shown   布局层是否保留（碰撞隐藏时为 false）。
383	 * @param dot_on  连接点是否实心（仅 GPS/BLE 有连接点）。
384	 */
385	static void sb_slot_apply(int k, sb_tone_t tone, bool shown, bool dot_on)
386	{
387	    sb_slot_t * s = &s_slot[k];
388	
389	    if (k == SB_BAT) {
390	        /* 自绘电池：体/极/填充同色；显隐与 tone 一起处理（ico 为 NULL）。 */
391	        const bool show = shown && tone != SB_TONE_HIDE;
392	        lv_color_t c = sb_tone_color(tone);
393	
394	        if (!show) {
395	            sb_hide(s_batt_body);
396	            sb_hide(s_batt_nub);
397	            s->vis_last = false;
398	            s->tone_last = SB_TONE_HIDE;
399	            return;
400	        }
401	        if (s_batt_body != NULL) {
402	            sb_show(s_batt_body);
403	            lv_obj_set_style_border_color(s_batt_body, c, 0);
404	        }
405	        if (s_batt_fill != NULL) {
406	            lv_obj_set_style_bg_color(s_batt_fill, c, 0);
407	        }
408	        if (s_batt_nub != NULL) {
409	            sb_show(s_batt_nub);
410	            lv_obj_set_style_bg_color(s_batt_nub, c, 0);
411	        }
412	        s->vis_last = true;
413	        s->tone_last = (uint8_t)tone;
414	        return;
415	    }
416	
417	    if (s->ico == NULL) {
418	        return;
419	    }
420	
421	    if (!shown || tone == SB_TONE_HIDE) {
422	        if (s->vis_last || !lv_obj_has_flag(s->ico, LV_OBJ_FLAG_HIDDEN)) {
423	            sb_hide(s->ico);
424	            s->vis_last = false;
425	        }
426	        if (s->dot != NULL &&
427	            (s->dot_last != 0 ||
428	             !lv_obj_has_flag(s->dot, LV_OBJ_FLAG_HIDDEN))) {
429	            sb_hide(s->dot);
430	            s->dot_last = 0;
431	        }
432	        s->tone_last = SB_TONE_HIDE;
433	        return;
434	    }
435	
436	    if (!s->vis_last) {
437	        sb_show(s->ico);
438	        s->vis_last = true;
439	        s->tone_last = SB_TONE_NONE;   /* 重新取色 */
440	    }
441	
442	    {
443	        bool tone_changed = (s->tone_last != (uint8_t)tone);
444	
445	        if (tone_changed) {
446	            lv_obj_set_style_text_color(s->ico, sb_tone_color(tone), 0);
447	            s->tone_last = (uint8_t)tone;
448	        }
449	
450	        if (s->dot != NULL) {
451	            const uint8_t want = dot_on ? 1u : 2u;
452	
453	            if (want != s->dot_last || tone_changed) {
454	                lv_color_t c = sb_tone_color(tone);
455	
456	                if (want == 1u) {
457	                    lv_obj_set_style_bg_color(s->dot, c, 0);
458	                    lv_obj_set_style_bg_opa(s->dot, LV_OPA_COVER, 0);
459	                    lv_obj_set_style_border_width(s->dot, 0, 0);
460	                } else {
461	                    lv_obj_set_style_bg_opa(s->dot, LV_OPA_TRANSP, 0);
462	                    lv_obj_set_style_border_width(s->dot, 1, 0);
463	                    lv_obj_set_style_border_color(s->dot, c, 0);
464	                    lv_obj_set_style_border_opa(s->dot, LV_OPA_COVER, 0);
465	                }
466	                sb_show(s->dot);
467	                s->dot_last = want;
468	            }
469	        }
470	    }
