507	/* ── 墨迹布局 ───────────────────────────────────────────────────────── */
508	
509	/** @brief 左簇：从 x0 往右打包；返回左簇末墨迹 x1。pos[] = 各图标墨迹 x0。 */
510	static int sb_left_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
511	                          int pos[5])
512	{
513	    const bool on[5] = { true, ble, hr, pwr, cad };
514	    int x = x0;
515	    int end = x - 1;
516	
517	    for (int i = 0; i < 5; i++) {
518	        if (!on[i]) {
519	            pos[i] = -1;
520	            continue;
521	        }
522	        pos[i] = x;
523	        end = x + s_slot[i].ink_w - 1;
524	        x = end + 1 + SB_INK_GAP_ICON;
525	    }
526	    return end;
527	}
528	
529	/**
530	 * @brief 右簇：电量图标**墨迹右沿钉在 238**，从右往左打包（全部按墨迹间隙算）。
531	 *
532	 * pos[0]=REC 墨迹 x0、pos[1]=NAV、pos[2]=电量图标；-1 = 隐藏。
533	 * 电量不显示百分比，图标就是右簇最右一项。
534	 */
535	static int sb_right_layout(bool rec, bool nav, int pos[3])
536	{
537	    int x;
538	    int left;
539	
540	    pos[2] = SB_BATT_INK_RIGHT - s_slot[SB_BAT].ink_w + 1;
541	    left = pos[2];
542	    /* x = 紧邻左侧那一项的**右边界（不含）**；NAV 隐藏时 REC 直接用
543	     * “NAV→电量 8” 的间隙贴到电量左边（模拟器 right_layout 同一规则）。 */
544	    x = pos[2] - SB_INK_GAP_NAV_BAT;
545	    pos[1] = nav ? (x - s_slot[SB_NAV].ink_w) : -1;
546	    if (nav) {
547	        left = pos[1];
548	        x = pos[1] - SB_INK_GAP_REC_NAV;
549	    }
550	    pos[0] = rec ? (x - SB_REC_D) : -1;
551	    if (rec) {
552	        left = pos[0];
553	    }
554	    return left;
555	}
556	
557	static uint32_t sb_layout_make_key(int time_ink_w, bool ble,
558	                                   bool hr, bool pwr, bool cad, bool rec,
559	                                   bool nav)
560	{
561	    uint32_t key = (uint32_t)(time_ink_w & 0x3F);
562	
563	    key = key * 2u + (ble ? 1u : 0u);
564	    key = key * 2u + (hr ? 1u : 0u);
565	    key = key * 2u + (pwr ? 1u : 0u);
566	    key = key * 2u + (cad ? 1u : 0u);
567	    key = key * 2u + (rec ? 1u : 0u);
568	    key = key * 2u + (nav ? 1u : 0u);
569	    return key;
570	}
571	
572	/**
573	 * @brief 按墨迹规则排两簇；碰撞时按 踏频→功率→NAV→BLE 依次隐藏。
574	 *
575	 * @details 布局只依赖「时间宽度、六个可隐藏项是否在」——这些都没变的 1 s 拍
576	 *          直接跳过，不碰对象位置。右簇右端固定 238（电量图标墨迹右沿）。
577	 */
578	static void sb_layout(int time_ink_w, bool ble, bool hr,
579	                      bool pwr, bool cad, bool rec, bool nav)
580	{
581	    const uint32_t key = sb_layout_make_key(time_ink_w, ble, hr, pwr, cad,
582	                                            rec, nav);
583	    const int x0 = SB_TIME_X + time_ink_w + SB_INK_GAP_TIME;   /* 时间墨迹 x1+1+6 */
584	    int pos[5];
585	    int rpos[3];
586	    int left_end;
587	    int right_left;
588	
589	    if (s_has_layout && key == s_layout_key) {
590	        return;
591	    }
592	    s_layout_key = key;
593	    s_has_layout = true;
594	
595	    for (int guard = 0; guard < 5; guard++) {
596	        left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
597	        right_left = sb_right_layout(rec, nav, rpos);
598	        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
599	            break;
600	        }
601	        if (cad) {
602	            cad = false;
603	        } else if (pwr) {
604	            pwr = false;
605	        } else if (nav) {
606	            nav = false;
607	        } else if (ble) {
608	            ble = false;
609	        } else {
610	            break;
611	        }
612	    }
613	
614	    left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
615	    right_left = sb_right_layout(rec, nav, rpos);
616	    (void)left_end;
617	    (void)right_left;
618	
619	    for (int i = 0; i < 5; i++) {
620	        s_ink_x[i] = pos[i];
621	        s_shown[i] = (pos[i] >= 0);
622	    }
623	    s_ink_x[SB_NAV] = rpos[1];
624	    s_shown[SB_NAV] = (rpos[1] >= 0);
625	    s_ink_x[SB_BAT] = rpos[2];
626	    s_shown[SB_BAT] = (rpos[2] >= 0);
627	    s_rec_x = rpos[0];
628	
629	    for (int k = 0; k < SB_SLOT_N; k++) {
630	        if (s_shown[k]) {
631	            sb_slot_place(k);
632	        }
633	    }
634	}
