636	/* ── 数据 → 语义色 ─────────────────────────────────────────────────── */
637	
638	static sb_tone_t sb_gps_tone(const bicycle_runtime_t * rt)
639	{
640	    bool alive = rt && rt->gnss_alive;
641	    bool valid = rt && rt->gnss_valid;
642	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
643	    uint8_t sats = rt ? rt->gnss_satellites : 0;
644	    uint8_t hdop = rt ? rt->gnss_hdop_x10 : 0;
645	
646	    /* 旧：失联红 / 未定位白 / 弱黄闪 / 正常绿。新：红 / 浅灰 / 红 / 墨色。 */
647	    if (!alive) {
648	        return SB_TONE_RED;
649	    }
650	    if (!valid) {
651	        return SB_TONE_TRACK;
652	    }
653	    if (q <= 1 || sats < 5 || hdop > 20) {
654	        return SB_TONE_RED;
655	    }
656	    return SB_TONE_INK;
657	}
658	
659	static sb_tone_t sb_ble_tone(bool radio_on, bool connected)
660	{
661	    /* 左簇的五个图标**位置固定**：蓝牙关着也占位（浅灰），不整颗消失，
662	     * 否则其余图标会跟着左移，和环心/骑行页的对齐口径对不上。 */
663	    if (!radio_on) {
664	        return SB_TONE_TRACK;
665	    }
666	    /* 旧：诊断异常红闪 10 s。新：红色常亮（不再有动画）。 */
667	    if (myvendor_diag_ble_unhealthy_age_ms() < SB_BLE_ALERT_MS) {
668	        return SB_TONE_RED;
669	    }
670	    return connected ? SB_TONE_INK : SB_TONE_TRACK;
671	}
