673	/** @brief 传感器图标：**始终占位**；就绪墨色，未配对/未就绪浅灰。 */
674	static void sb_sensor_tones(sb_tone_t tone[SB_SLOT_N])
675	{
676	    static const uint8_t slot_of_kind[MYVENDOR_SYS_SENSOR_KIND_N] = {
677	        SB_HR, SB_CAD, SB_PWR,
678	    };
679	    myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
680	    myvendor_sys_sensor_ui_t ui;
681	    size_t n = 0;
682	    size_t i;
683	    uint8_t k;
684	    bool want[MYVENDOR_SYS_SENSOR_KIND_N];
685	    bool sensor_on = myvendor_devctl_sensor_get();
686	
687	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
688	        want[k] = false;
689	    }
690	
691	    if (sensor_on &&
692	        myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
693	                                        &n) == 0) {
694	        for (i = 0; i < n; i++) {
695	            if (recs[i].autorc && recs[i].kind < MYVENDOR_SYS_SENSOR_KIND_N) {
696	                want[recs[i].kind] = true;
697	            }
698	        }
699	    }
700	
701	    myvendor_sys_sensor_ui_get(&ui);
702	
703	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
704	        const uint8_t slot = slot_of_kind[k];
705	        bool ready = (ui.slot[k].link == MYVENDOR_SYS_SENSOR_LINK_READY);
706	
707	        /* 关功能/未配对也画浅灰占位（设计口径：五个图标常驻，靠颜色区分）。 */
708	        tone[slot] = (sensor_on && want[k] && ready) ? SB_TONE_INK
709	                                                     : SB_TONE_TRACK;
710	    }
711	}
712	
713	static void sb_time_update(void)
714	{
715	    time_t now = time(NULL);
716	    int hour = -1;
717	    int min = -1;
718	
719	    if (now >= 1704067200) {
720	        if (!myvendor_devctl_tz_hms((long)now, &hour, &min)) {
721	            hour = -1;
722	            min = -1;
723	        }
724	    }
725	
726	    if (hour < 0) {
727	        myvendor_sys_gnss_t cfix;
728	        bool got = myvendor_sys_onboard_gnss_get(&cfix);
729	
730	        if (!got) {
731	            got = myvendor_sys_phone_gnss_get(&cfix);
732	        }
733	
734	        if (got && cfix.utc_sec >= 1704067200u) {
735	            time_t utc = (time_t)cfix.utc_sec;
736	            struct timeval tv;
737	
738	            tv.tv_sec = utc;
739	            tv.tv_usec = 0;
740	            (void)settimeofday(&tv, NULL);
741	            if (!myvendor_devctl_tz_hms((long)utc, &hour, &min)) {
742	                hour = -1;
743	                min = -1;
744	            }
745	        }
746	    }
747	
748	    if (hour < 0) {
749	        (void)bicycle_gpx_sim_get_wall_hms(&hour, &min);
750	    }
751	
752	    if (hour < 0) {
753	        hour = 0;
754	        min = 0;
755	    }
756	
757	    {
758	        const uint16_t hm = (uint16_t)(hour * 60 + min);
759	
760	        if (hm != s_last_time_hm) {
761	            sb_text_metrics_t m;
762	
763	            lv_snprintf(s_time_buf, sizeof(s_time_buf), "%02d:%02d", hour, min);
764	            lv_label_set_text(s_time, s_time_buf);
765	            sb_text_measure(s_time_buf, &m);
766	            /* 首字有 side bearing 时把 label 反向外移 ⇒ 墨迹恒定从 x=12 起。 */
767	            lv_obj_set_x(s_time, SB_TIME_X - m.ink_x0);
768	            s_time_ink_w = m.ink_w;
769	            s_last_time_hm = hm;
770	        }
771	    }
772	}
