774	static void sb_battery_update(void)
775	{
776	    const int inner = SB_BATT_BODY_W - 2;   /* 只扣 1px 边框：填充贴边框 */
777	    int pct = s_battery_pct;
778	    int w;
779	
780	    if (pct < 0) {
781	        w = 0;
782	    } else {
783	        if (pct > 100) {
784	            pct = 100;
785	        }
786	        w = inner * pct / 100;
787	        if (w < 1 && pct > 0) {
788	            w = 1;
789	        }
790	    }
791	
792	    /* 自绘电池：只改填充宽度；颜色由 sb_slot_apply(SB_BAT) 按 tone 上。 */
793	    if (s_batt_fill != NULL) {
794	        lv_obj_set_width(s_batt_fill, w);
795	    }
796	}
