798	static void status_bar_refresh(void)
799	{
800	    const bicycle_runtime_t * rt = bicycle_runtime_get();
801	    sb_tone_t tone[SB_SLOT_N];
802	    bool dot_on[SB_SLOT_N];
803	    bool ble;
804	    bool rec, nav, paused;
805	    int time_w;
806	
807	    if (s_time == NULL) {
808	        return;
809	    }
810	
811	    bicycle_status_bar_set_battery_pct(s_batt_demo >= 0 ? s_batt_demo
812	                                                        : myvendor_sys_battery_percent());
813	
814	    sb_palette_apply(false);
815	    sb_time_update();
816	    sb_battery_update();
817	
818	    for (int k = 0; k < SB_SLOT_N; k++) {
819	        tone[k] = SB_TONE_HIDE;
820	        dot_on[k] = false;
821	    }
822	
823	    /* 左簇：GPS 恒在；BLE 关电台才隐藏；心率/功率/踏频看配对。 */
824	    tone[SB_GPS] = sb_gps_tone(rt);
825	    dot_on[SB_GPS] = rt && rt->gnss_valid;
826	
827	    ble = myvendor_devctl_radio_get();
828	    tone[SB_BLE] = sb_ble_tone(ble, myvendor_sys_phone_ble_connected());
829	    dot_on[SB_BLE] = myvendor_sys_phone_ble_connected();
830	
831	    sb_sensor_tones(tone);
832	
833	    /* REC：记录中红、暂停灰；未记录隐藏（旧 PAUSE 药丸并入 REC 颜色）。
834	     * R1-S4a：真实暂停路径（map_page_pause_ride）会把 runtime.recording 置 false
835	     * —— 那表示"计时暂停"，不是"没有骑行"。REC 的可见性必须同时看 paused，
836	     * 否则暂停后圆点直接消失，设计里"暂停 = 灰点"就永远走不到。 */
837	    paused = helm_shell_paused();
838	    rec = rt && (rt->recording || paused);
839	
840	    /* NAV：导航中蓝，未导航隐藏。 */
841	    nav = map_page_nav_active(live_map_page_instance());
842	    tone[SB_NAV] = nav ? SB_TONE_BLUE : SB_TONE_HIDE;
843	
844	    /* 电量：<20% 红；未知 = 浅灰；图标字形按 20/60 分级。 */
845	    if (s_battery_pct < 0) {
846	        tone[SB_BAT] = SB_TONE_TRACK;
847	    } else if (s_battery_pct < 20) {
848	        tone[SB_BAT] = SB_TONE_RED;
849	    } else {
850	        tone[SB_BAT] = SB_TONE_INK;
851	    }
852	
853	    /* 布局：先把本拍数据层的可见性取出来算两簇，再统一上色。 */
854	    time_w = s_time_ink_w;
855	
856	    sb_layout(time_w,
857	              tone[SB_BLE] != SB_TONE_HIDE,
858	              tone[SB_HR] != SB_TONE_HIDE,
859	              tone[SB_PWR] != SB_TONE_HIDE,
860	              tone[SB_CAD] != SB_TONE_HIDE,
861	              rec, nav);
862	
863	    for (int k = 0; k < SB_SLOT_N; k++) {
864	        sb_slot_apply(k, tone[k], s_shown[k], dot_on[k]);
865	    }
866	
867	    /* 电量只有图标：颜色在 sb_slot_apply 里按 tone 上（<20% 红）。 */
868	    sb_rec_apply(rec, paused);
869	}
